//! Setup pins, translated from tests/test_setup.py with the
//! port pins of PORT-9 added.
//!
//! Each translated pin can fail for a real reason against a
//! repo that lost a setup file or let its status drift from
//! its contract. The port pins hold the README port line to
//! exactly one standing, the CI cargo steps and the scan
//! through the codepoint_scan binary, and the contract
//! port items in place.

mod shared;

use shared::*;

fn root_text(relative: &str) -> String {
    read_text(&repo_root().join(relative))
}

fn lines_of(text: &str) -> Vec<&str> {
    text.lines().collect()
}

#[test]
fn agents_carries_the_canonical_marker() {
    let text = root_text("AGENTS.md");
    assert!(text.contains("<!-- repo annex below this line -->"));
    assert!(text.contains("39 repo storefront perfection program"));
}

#[test]
fn readme_states_the_closed_round_count() {
    let text = root_text("README.md");
    assert!(text.contains("Closed perfection rounds, 26 of 100"));
}

// The whole obligation assertion cure of Round 27 stands
// completed at this pin and at every contract carrying pin
// beside it. Each asserts its texts whole inside the
// sections their headings open, where the pins as landed
// asserted the identifier alone over the whole contract.
// Each pin asserts beside the whole text that each heading
// it guards stands once in the contract and that the section
// the heading opens carries the heading and the whole text
// and nothing else, so a paragraph cut in its place falls at
// its pin though its whole text stands duplicated behind the
// cut inside its own section, and though its whole text
// stands under a second standing of its heading planted
// ahead of its own. The body cut stands executed on the
// Round 27 slice tree at each of the ninety seven seats the
// cure reaches, and at the cuts of the setup section and of
// GJ-1 this pin falls alone. On the Round 26 closure tree
// the cut of GJ-1 passes whole and the cut of the setup
// section falls at this pin as landed, its construction
// removing the middle setup items whole and with them the
// only standing of SETUP-2 anywhere in the contract, the one
// seat where a presence assertion catches a body cut. This
// block asserts nothing.
#[test]
fn contract_carries_the_setup_obligations() {
    let text = root_text("CONTRACT.md");
    let lines = lines_of(&text);
    let setup_section = contract_section(&text, "## Setup obligations");
    assert!(setup_section.contains("- SETUP-1. The repo carries AGENTS.md with the canonical template verbatim\n  above its marked line and the repo annex below it. Test,\n  tests/test_setup.py.\n- SETUP-2. The README programme status states the closed round count out\n  of 100 and reports this Contract as met or not met. Test,\n  tests/test_setup.py.\n- SETUP-3. The codepoint scan at scripts/codepoint_scan.py counts U+2014\n  and U+2013 in every Markdown and text file in the repo and requires\n  zero of each. The scan runs in the local gate and in CI.\n- SETUP-4. Every fixture and example committed to this repo is synthetic\n  and written for this repo. Nothing real is ever committed. Check, a\n  manual sanitization review of every added fixture and example, with\n  its result recorded in the gate report."));
    assert_eq!(
        lines
            .iter()
            .filter(|line| **line == "## Setup obligations")
            .count(),
        1
    );
    assert_eq!(
        setup_section,
        "## Setup obligations\n\n- SETUP-1. The repo carries AGENTS.md with the canonical template verbatim\n  above its marked line and the repo annex below it. Test,\n  tests/test_setup.py.\n- SETUP-2. The README programme status states the closed round count out\n  of 100 and reports this Contract as met or not met. Test,\n  tests/test_setup.py.\n- SETUP-3. The codepoint scan at scripts/codepoint_scan.py counts U+2014\n  and U+2013 in every Markdown and text file in the repo and requires\n  zero of each. The scan runs in the local gate and in CI.\n- SETUP-4. Every fixture and example committed to this repo is synthetic\n  and written for this repo. Nothing real is ever committed. Check, a\n  manual sanitization review of every added fixture and example, with\n  its result recorded in the gate report.\n"
    );
    let gj1 = contract_section(
        &text,
        "### GJ-1 full form, the loader names every malformed field and never raises",
    );
    assert!(gj1.contains("The loader entry points are load_poll_text and load_poll_file in the grandjury.polls module. Each returns a pair of the poll and the list of defects it found. A clean input returns the poll and an empty defect list. A malformed input returns no poll and a defect list naming every malformed field the loader could reach, and neither entry point ever raises on malformed content. A file that cannot be read returns the single defect named file cannot be read. The defect vocabulary is fixed, and a test pins each phrase. Text that is not JSON at all draws the defect named input is not valid JSON, and JSON nested too deeply to parse draws the same defect. JSON that parses to something other than an object draws the defect named input is not a JSON object. An absent field draws missing field and the field name. A field of the wrong kind draws field and the field name and has the wrong type. An empty question draws field question is empty. A text field holding an unpaired surrogate draws field and the field name and holds an unpaired surrogate, and the same naming applies inside answers and inside responses with their own prefixes below. An answers list holding fewer than two entries draws field answers holds fewer than two answers. An offered answer of the wrong kind draws answer and its index and has the wrong type, an empty one draws answer and its index and is empty, and one holding an unpaired surrogate draws answer and its index and holds an unpaired surrogate. An offered answer that stands twice draws duplicate answer and the answer itself. A responses entry that is not an object draws response and its index and is not an object, and response indexes count from zero. A response missing a field draws response and its index and is missing field and the field name. A response field of the wrong kind draws response and its index and field and the field name and has the wrong type. An empty response field draws response and its index and field and the field name and is empty. A response text field holding an unpaired surrogate draws response and its index and field and the field name and holds an unpaired surrogate. A reason holding a newline character draws response and its index and field reason holds a newline. A juror string that stands twice draws duplicate juror and the juror string itself. One malformed input can draw several defects in one pass, and the loader keeps naming fields after the first defect it finds. Test, tests/test_polls.py."));
    assert_eq!(
        lines
            .iter()
            .filter(|line| **line
                == "### GJ-1 full form, the loader names every malformed field and never raises")
            .count(),
        1
    );
    assert_eq!(
        gj1,
        "### GJ-1 full form, the loader names every malformed field and never raises\n\nThe loader entry points are load_poll_text and load_poll_file in the grandjury.polls module. Each returns a pair of the poll and the list of defects it found. A clean input returns the poll and an empty defect list. A malformed input returns no poll and a defect list naming every malformed field the loader could reach, and neither entry point ever raises on malformed content. A file that cannot be read returns the single defect named file cannot be read. The defect vocabulary is fixed, and a test pins each phrase. Text that is not JSON at all draws the defect named input is not valid JSON, and JSON nested too deeply to parse draws the same defect. JSON that parses to something other than an object draws the defect named input is not a JSON object. An absent field draws missing field and the field name. A field of the wrong kind draws field and the field name and has the wrong type. An empty question draws field question is empty. A text field holding an unpaired surrogate draws field and the field name and holds an unpaired surrogate, and the same naming applies inside answers and inside responses with their own prefixes below. An answers list holding fewer than two entries draws field answers holds fewer than two answers. An offered answer of the wrong kind draws answer and its index and has the wrong type, an empty one draws answer and its index and is empty, and one holding an unpaired surrogate draws answer and its index and holds an unpaired surrogate. An offered answer that stands twice draws duplicate answer and the answer itself. A responses entry that is not an object draws response and its index and is not an object, and response indexes count from zero. A response missing a field draws response and its index and is missing field and the field name. A response field of the wrong kind draws response and its index and field and the field name and has the wrong type. An empty response field draws response and its index and field and the field name and is empty. A response text field holding an unpaired surrogate draws response and its index and field and the field name and holds an unpaired surrogate. A reason holding a newline character draws response and its index and field reason holds a newline. A juror string that stands twice draws duplicate juror and the juror string itself. One malformed input can draw several defects in one pass, and the loader keeps naming fields after the first defect it finds. Test, tests/test_polls.py.\n"
    );
}

#[test]
fn readme_reports_the_contract_status() {
    let text = root_text("README.md");
    let expected = "- Contract, SETUP-1 to SETUP-4 and GJ-1 to GJ-4 met. GJ-1 to GJ-4 stand in full form in CONTRACT.md with the Round 1 repair amendments, and Round 1 closed on the merged slice 2 after three reviews, a repair pass, and an approving re-review.";
    assert!(lines_of(&text).contains(&expected));
}

